import {SCENES,TOTAL_SECONDS,DemoClock,createDemoScenario,faultAt} from './demo-core.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=x=>`$${x.toFixed(2)}`,pct=x=>`${Math.round(x*100)}%`,time=s=>`${Math.floor(s/60)}:${String(Math.floor(s%60)).padStart(2,'0')}`;
const ease=t=>1-(1-Math.max(0,Math.min(1,t)))**3;
const head=(title,tag='')=>`<div class="panel-head"><h2>${title}</h2>${tag?`<span class="chip">${tag}</span>`:''}</div>`;
const metric=(label,value,note='',accent=false)=>`<div class="demo-metric ${accent?'accent':''}">${label}<strong>${value}</strong>${note}</div>`;
function spark(rows,key,color='#a5be85',range){const values=rows.map(x=>x[key]),lo=range?.[0]??Math.min(...values)-.1,hi=range?.[1]??Math.max(...values)+.1;const d=values.map((v,i)=>`${i?'L':'M'}${(i/(values.length-1)*240).toFixed(1)},${(57-(v-lo)/(hi-lo)*48).toFixed(1)}`).join(' ');return `<svg class="demo-spark" viewBox="0 0 240 65" preserveAspectRatio="none" aria-hidden="true"><path d="${d}" fill="none" stroke="${color}" stroke-width="2.2" stroke-linecap="round"/></svg>`;}
function sensor(rows,label,key,unit,color,token=''){const v=rows.at(-1)[key];return `<div class="demo-sensor"><span>${label}</span><strong ${token?`data-demo-value="${token}"`:''}>${v.toFixed(2)} <small>${unit}</small></strong>${spark(rows,key,color)}</div>`;}
function lockup(){return `<div class="demo-intro-lockup"><div class="demo-intro-mark">F</div><div class="demo-wordmark">Forge<span>Sight</span></div></div>`;}
function miniFleet(fleet,printer){return `<div class="fleet-grid">${fleet.map(m=>`<div class="machine ${m.id==='P03'?'selected':''} ${m.concern>.4?'alert':''}"><div class="machine-top"><strong>${m.id} / ${m.name}</strong><span class="chip ${m.concern>.4?'orange':''}">${m.concern>.4?'INSPECT':'NORMAL'}</span></div><div class="machine-name">${m.materials.join(' + ')} / ${m.speed.toFixed(2)}× speed</div>${printer(m)}<div class="machine-score"><span>Anomaly score</span><b>${pct(m.concern)}</b></div><div class="meter"><i style="width:${Math.max(3,m.concern*100)}%"></i></div><div class="machine-job"><span>Available in ${m.available}m</span><span>FDM</span></div></div>`).join('')}</div>`;}
function scores(result){return result.scores.map((s,i)=>`<div class="demo-score-row ${i===result.index?'active':''}"><div><span>${['Normal','Blockage','Thermal','Vibration'][i]}</span><b>${pct(s)}</b></div><div class="meter"><i style="width:${Math.max(.7,s*100)}%"></i></div></div>`).join('');}
function movingPlan(s){return `<div class="demo-plan-motion">${s.fleet.map((m,i)=>`<div class="demo-lane" style="top:${i*44}px"><span>${m.id}</span></div>`).join('')}${s.base.rows.map(r=>`<div class="demo-moving-job ${r.delay?'late':''}" data-demo-job="${r.id}"><i>${r.id}</i></div>`).join('')}</div><div class="demo-stage-badge"><span>0 → ${Math.round(Math.max(s.base.makespan,s.plan.makespan))} minutes</span><b data-demo-plan-label>Baseline assignment</b></div>`;}
function planStatic(plan,fleet){const max=Math.max(300,plan.makespan);return `<div class="gantt">${fleet.map(m=>`<div class="gantt-row"><span>${m.id}</span><div class="gantt-track">${plan.rows.filter(r=>r.machineId===m.id).map(r=>`<div class="gantt-bar ${r.delay?'delayed':''}" style="left:${r.start/max*100}%;width:${(r.end-r.start)/max*100}%">${r.id}</div>`).join('')}${m.offline?'<span style="position:absolute;left:10px;top:10px;font-size:8px;color:#af9f81">OFFLINE / no new orders</span>':''}</div></div>`).join('')}</div>`;}
export function sceneVisual(id,s,printer=()=>'',r=s.fleet[2].result){
  const rows=s.fleet[2].rows;
  if(id==='intro')return `<div class="demo-intro-orbit">${lockup()}<div class="demo-chipline"><span class="demo-pill">01 / MONITOR</span><span class="demo-pill">02 / DETECT</span><span class="demo-pill">03 / OPTIMIZE</span></div></div>`;
  if(id==='problem')return `<div class="panel">${head('The queue keeps moving.','PRINT FARM')}<div class="demo-waste-banner"><b>⌁</b><span>Machine issues affect more than the current print.</span></div>${s.queue.slice(0,3).map((j,i)=>`<div class="demo-order-card"><div class="order-icon">${['▱','▧','◈'][i]}</div><div><strong>${j.id} / ${j.name}</strong><small>${j.material} · ${j.minutes} min of print time</small></div><span class="chip">Due ${j.due}m</span></div>`).join('')}<div class="demo-metric-row">${metric('QUEUE SIZE','12','unstarted orders')}${metric('ORDER VALUE',money(s.orderValue),'example business data')}${metric('MACHINES','06','available in sandbox')}</div></div>`;
  if(id==='floor')return `<div class="panel">${head('Your production floor','SYNTHETIC LIVE VIEW')}${miniFleet(s.healthy,printer)}<p class="demo-small-note">Online status, material support, and next availability all affect scheduling.</p></div>`;
  if(id==='telemetry'){const h=s.healthy[2].rows;return `<div class="panel">${head('P03 / Cinder · Sensor window','30 SAMPLES')}<div class="demo-legend"><span>10 seconds per sample</span><span class="demo-live">NORMAL PATTERN</span></div><div class="demo-sensor-grid">${sensor(h,'TEMPERATURE','temp_c','°C','#b6c994')}${sensor(h,'VIBRATION','vibration_mm_s','mm/s','#b6c994')}${sensor(h,'MOTOR CURRENT','motor_a','A','#c7b691')}${sensor(h,'EXTRUSION FLOW','extrusion_mm_s','mm/s','#c7b691')}</div><p class="demo-small-note">Each window becomes six standardized features before classification.</p></div>`;}
  if(id==='fault')return `<div class="panel">${head('P03 / Changing operating conditions','FAULT INJECTION')}<div class="demo-fault-hero"><div><h3 data-demo-pattern>Normal operation</h3><p>Generated extrusion-blockage scenario</p></div><div class="demo-risk"><strong data-demo-value="risk">0%</strong><small>model anomaly score</small></div></div><div class="demo-sensor-grid">${sensor(rows,'MOTOR CURRENT','motor_a','A','#d69b63','motor')}${sensor(rows,'EXTRUSION FLOW','extrusion_mm_s','mm/s','#d69b63','extrusion')}</div><div class="meter" style="height:7px;margin-top:24px"><i data-demo-riskbar style="width:0;background:#e0a16c"></i></div><p class="demo-small-note">1 − normal class score · Computed from the changing observation window.</p></div>`;
  if(id==='evidence'){const labels={temperature_std_c:'Temperature variation',temperature_slope_c_per_sample:'Temperature trend',motor_mean_a:'Motor current',vibration_mean_mm_s:'Vibration',extrusion_mean_mm_s:'Extrusion flow',extrusion_slope_mm_s_per_sample:'Extrusion trend'};return `<div class="panel">${head('P03 / Explain the classification','MODEL EVIDENCE')}<div class="demo-fault-hero"><div><h3>${esc(r.label)}</h3><p>Pattern identified in generated telemetry</p></div><div class="demo-risk"><strong>${pct(r.concern)}</strong><small>anomaly score</small></div></div><div class="demo-evidence-grid"><div><h3>Class scores</h3>${scores(r)}</div><div><h3>Strongest signal deviations</h3>${r.contributions.slice(0,3).map(x=>`<div class="demo-deviation"><span>${labels[x.name]}</span><b>${x.deviation.toFixed(1)}σ</b></div>`).join('')}<p class="demo-small-note">σ = distance from the synthetic healthy baseline, in standard deviations.</p></div></div><p class="demo-small-note">Inspection suggestion: check the nozzle and filament path before assigning new work.</p></div>`;}
  if(id==='patterns')return `<div class="panel">${head('Learned fault signatures','FOUR-CLASS MODEL')}<div class="demo-patterns">${s.patterns.map((p,i)=>`<div class="demo-pattern"><div class="demo-pattern-icon">${['↘','⌁','≋'][i]}</div><div><strong>${esc(p.result.label)}</strong><small>${['Higher motor load · lower extrusion flow','Temperature oscillation · rising trend','Elevated vibration · increased motor load'][i]}</small></div><div class="demo-pattern-score">${pct(p.result.concern)}</div></div>`).join('')}</div><p class="demo-small-note">Percentages are anomaly scores from three separate synthetic windows.</p></div>`;
  if(id==='baseline')return `<div class="panel">${head('The baseline under the fault scenario','CALCULATED')}<div class="demo-metric-row">${metric('SCENARIO COST',money(s.base.cost),'penalties + waste proxy',true)}${metric('LATE ORDERS',s.base.late,'round-robin dispatch',true)}${metric('WASTE PROXY',money(s.base.exposure),'risk-weighted estimate')}</div>${planStatic(s.base,s.fleet)}<div class="demo-assumptions"><span>Disruption at max score: 60m</span><span>Late penalty: $12/h</span><span>Machine cost: $3/h</span></div><p class="demo-small-note">A stated cost model, not measured profit or physical failure probability.</p></div>`;
  if(id==='optimize')return `<div class="panel">${head('Reassign the future queue','LOCAL SEARCH')}${movingPlan(s)}<p class="demo-small-note">Motion connects computed baseline and proposed assignments. It does not show elapsed physical print time.</p><div class="demo-assumptions"><span>Deadline-aware</span><span>Material compatible</span><span>Existing jobs stay put</span></div></div>`;
  if(id==='results'){const d=s.base.cost-s.plan.cost;return `<div class="panel">${head('Before / after for this scenario','COMPUTED COMPARISON')}<div class="comparison"><div class="comparison-box"><span>ROUND-ROBIN BASELINE</span><strong>${money(s.base.cost)}</strong><small>${s.base.late} late orders</small></div><div class="comparison-arrow">→</div><div class="comparison-box after"><span>PROPOSED SCHEDULE</span><strong>${money(s.plan.cost)}</strong><small>${s.plan.late} late orders</small></div></div><div class="demo-reduction"><strong>${pct(d/s.base.cost)}</strong><span>lower calculated objective<br>${money(d)} difference in this scenario</span></div><div class="demo-metric-row">${metric('MOVED ORDERS',s.moved,'different machine')}${metric('CURRENT JOBS','FIXED','only future work is planned')}${metric('PHYSICAL COMMANDS','NONE','sandbox recommendation')}</div><p class="demo-small-note">Real-world savings and reliability have not been measured.</p></div>`;}
  if(id==='offline')return `<div class="panel">${head('One machine offline. Replan.','WHAT-IF SCENARIO')}<div class="demo-offline-card"><strong>P03 / Cinder</strong><span>OFFLINE · Excluded from new assignments</span></div>${planStatic(s.offlinePlan,s.offline)}<div class="demo-metric-row">${metric('AVAILABLE MACHINES','05','one removed')}${metric('SCENARIO COST',money(s.offlinePlan.cost),'recomputed objective')}${metric('LATE ORDERS',s.offlinePlan.late,'computed queue result')}</div><p class="demo-small-note">Every queued order uses an online, material-compatible machine.</p></div>`;
  if(id==='model'){const e=s.model.evaluation;return `<div class="panel">${head('The AI inside the application','LOGISTIC REGRESSION')}<div class="demo-model-chain"><div>30-sample window</div><span>→</span><div>6 scaled features</div><span>→</span><div>4 learned class scores</div></div><div class="stat-grid"><div>Training windows<b>${e.trainWindows.toLocaleString()}</b>Synthetic · seed 41</div><div>Test windows<b>${e.testWindows.toLocaleString()}</b>Held-out · seed 2026</div><div>Synthetic accuracy<b>${(e.accuracy*100).toFixed(2)}%</b>Same generator</div></div><div class="demo-matrix">${e.confusion.flatMap((row,i)=>row.map((n,j)=>`<div class="${i===j?'diagonal':''}">${n}</div>`)).join('')}</div><p class="demo-small-note">4 × 4 confusion matrix · Diagonal = correct classifications.<br>Good results on this simulator do not establish performance on real machines.</p></div>`;}
  if(id==='import')return `<div class="panel">${head('An open input format','LOCAL CSV ANALYSIS')}<div class="code">${esc(s.csv.split('\n').slice(0,8).join('\n'))}<br>…</div><div class="demo-import-flow"><span>CSV file</span>→<span>Browser ML</span>→<span>Queue planner</span></div><div class="demo-assumptions"><span>No API keys</span><span>No telemetry uploads</span><span>Exportable analysis</span></div><p class="demo-small-note">This view previews the supported schema. The dashboard supports actual file import; this recording does not upload a file.</p></div>`;
  return `<div class="demo-intro-orbit">${lockup()}<div class="demo-chipline"><span class="demo-pill">OBSERVE</span><span class="demo-pill">UNDERSTAND</span><span class="demo-pill">ACT</span></div><p class="demo-small-note" style="text-align:center;margin-top:28px">AI + Business / ForgeHacks 2026<br>AI-assisted development · Synthetic telemetry · Working browser prototype</p></div>`;
}

export function createAutoDemo({model,printer=()=>'',onOpen=()=>{},onClose=()=>{}}){
  let root=null,clock=null,scenario=null,raf=0,lastScene=-1,countdown=3,lastFrame=0,phase='idle',paused=false,previousFocus=null,savedOverflow='';
  const q=s=>root?.querySelector(s);
  function scene(position){const old=q('.demo-scene:not(.outgoing)');if(old){old.classList.add('outgoing');setTimeout(()=>old.remove(),550);}const el=document.createElement('section');el.className='demo-scene';el.setAttribute('aria-label',position.scene.title);el.innerHTML=`<div class="demo-copy"><span class="eyebrow">${position.scene.chapter}</span><h1>${position.scene.title}</h1><div class="chapter-line"></div><p class="demo-caption">${position.scene.caption}</p></div><div class="demo-visual">${sceneVisual(position.scene.id,scenario,printer)}</div>`;q('.demo-viewport').append(el);lastScene=position.index;updateVisual(position);}
  function updateVisual(p){
    const active=q('.demo-scene:not(.outgoing)');if(!active)return;
    if(p.scene.id==='fault'){
      const f=faultAt(p.progress,model),last=f.rows.at(-1);const set=(sel,value)=>{const x=active.querySelector(sel);if(x)x.innerHTML=value;};
      set('[data-demo-value="risk"]',pct(f.result.concern));set('[data-demo-value="motor"]',`${last.motor_a.toFixed(2)} <small>A</small>`);set('[data-demo-value="extrusion"]',`${last.extrusion_mm_s.toFixed(2)} <small>mm/s</small>`);set('[data-demo-pattern]',f.result.index?esc(f.result.label):'Normal operation');
      const bar=active.querySelector('[data-demo-riskbar]');if(bar)bar.style.width=pct(f.result.concern);
      const paths=active.querySelectorAll('.demo-spark path');['motor_a','extrusion_mm_s'].forEach((key,i)=>{const vs=f.rows.map(x=>x[key]);const lo=key==='motor_a'?1:1.2,hi=key==='motor_a'?3.5:4.8;paths[i]?.setAttribute('d',vs.map((v,k)=>`${k?'L':'M'}${(k/(vs.length-1)*240).toFixed(1)},${(57-(v-lo)/(hi-lo)*48).toFixed(1)}`).join(' '));});
    }
    if(p.scene.id==='optimize'){
      const t=ease((p.progress-.17)/.55),max=Math.max(scenario.base.makespan,scenario.plan.makespan);
      for(const item of active.querySelectorAll('[data-demo-job]')){const a=scenario.base.rows.find(x=>x.id===item.dataset.demoJob),b=scenario.plan.rows.find(x=>x.id===item.dataset.demoJob),ai=scenario.fleet.findIndex(m=>m.id===a.machineId),bi=scenario.fleet.findIndex(m=>m.id===b.machineId),bar=item.querySelector('i');item.style.transform=`translateY(${(ai+(bi-ai)*t)*44}px)`;bar.style.left=`${(a.start+(b.start-a.start)*t)/max*100}%`;bar.style.width=`${((a.end-a.start)+((b.end-b.start)-(a.end-a.start))*t)/max*100}%`;item.classList.toggle('late',t>.5?b.delay>0:a.delay>0);}
      const label=active.querySelector('[data-demo-plan-label]');label.textContent=t===0?'Baseline assignment':t<1?'Moving future assignments…':'Proposed schedule / calculated';
    }
  }
  function progress(p){q('[data-demo-progress]').style.width=`${p.elapsed/TOTAL_SECONDS*100}%`;q('[data-demo-time]').textContent=`${time(p.elapsed)} / ${time(TOTAL_SECONDS)}`;q('[data-demo-chapter]').textContent=p.scene.chapter;q('[data-demo-step]').textContent=`${String(p.index+1).padStart(2,'0')} / ${SCENES.length}`;q('[data-demo-play]').textContent=paused?'▶':'Ⅱ';q('[data-demo-play]').setAttribute('aria-label',paused?'Resume demo':'Pause demo');root.classList.toggle('demo-paused',paused);}
  function finish(){phase='finished';clock.pause();if(q('.demo-finished'))return;const el=document.createElement('div');el.className='demo-finished';el.innerHTML='<div><span class="eyebrow">3-MINUTE TOUR COMPLETE</span><h2>That’s ForgeSight.</h2><p>You can stop your recording now, replay the tour, or explore the working dashboard.</p><button class="btn primary" data-demo-replay>↻ Replay demo</button><button class="btn" data-demo-exit>Explore dashboard →</button></div>';q('.demo-viewport').append(el);el.querySelector('[data-demo-replay]').onclick=start;el.querySelector('[data-demo-exit]').onclick=stop;}
  function frame(now){if(!root)return;const delta=Math.max(0,(now-lastFrame)/1000);lastFrame=now;
    if(phase==='countdown'&&!paused){countdown-=delta;const number=q('[data-demo-countdown]');if(number)number.textContent=Math.max(1,Math.ceil(countdown));if(countdown<=0){q('.demo-countdown')?.remove();phase='running';clock.start(now);}}
    if(phase==='running'){const p=clock.tick(now);if(p.index!==lastScene)scene(p);if(!paused)updateVisual(p);progress(p);if(p.finished)finish();}
    raf=requestAnimationFrame(frame);
  }
  function playPause(){if(!root||phase==='finished')return;paused=!paused;if(paused)clock.pause();else clock.resume(performance.now());lastFrame=performance.now();progress(clock.position());}
  function seek(offset){if(!root)return;q('.demo-finished')?.remove();q('.demo-countdown')?.remove();phase='running';const target=Math.max(0,Math.min(SCENES.length-1,clock.position().index+offset)),p=clock.seek(target,performance.now());if(!paused)clock.resume(performance.now());scene(p);progress(p);}
  function visibility(){if(document.hidden&&!paused&&root)playPause();}
  function key(e){if(!root)return;if(e.key==='Escape'){e.preventDefault();stop();}else if(e.code==='Space'){e.preventDefault();playPause();}else if(e.key==='ArrowRight'){e.preventDefault();seek(1);}else if(e.key==='ArrowLeft'){e.preventDefault();seek(-1);}}
  function fullscreen(){if(!root)return;if(document.fullscreenElement){document.exitFullscreen?.().catch(()=>{});}else root.requestFullscreen?.().catch(()=>{});}
  function stop(){if(!root)return;cancelAnimationFrame(raf);if(document.fullscreenElement===root)document.exitFullscreen?.().catch(()=>{});root.remove();root=null;phase='idle';document.body.style.overflow=savedOverflow;document.removeEventListener('keydown',key);document.removeEventListener('visibilitychange',visibility);onClose();previousFocus?.focus?.();}
  function start(){if(root)stop();previousFocus=document.activeElement;savedOverflow=document.body.style.overflow;document.body.style.overflow='hidden';onOpen();scenario=createDemoScenario(model);clock=new DemoClock();paused=false;countdown=3;lastScene=-1;phase='countdown';lastFrame=performance.now();
    root=document.createElement('div');root.className='demo-theater';root.setAttribute('role','dialog');root.setAttribute('aria-modal','true');root.setAttribute('aria-label','ForgeSight automatic three-minute demo');root.tabIndex=-1;
    root.innerHTML=`<div class="demo-top"><div class="demo-brand"><span class="brandmark">F</span>ForgeSight<small>THE GUIDED DEMO</small></div><div class="demo-top-actions"><span class="demo-disclosure">SYNTHETIC DATA / WORKING ENGINE</span><button data-demo-fullscreen>⛶ Fullscreen</button><button data-demo-close>Exit ×</button></div></div><div class="demo-viewport"><span class="demo-pause-label">Paused · press Space to continue</span><div class="demo-countdown"><span>RECORDING READY · STARTING IN</span><strong data-demo-countdown>3</strong><span>ONE BUTTON. THE REST PLAYS ITSELF.</span></div></div><div class="demo-bottom"><div class="demo-playback"><button data-demo-prev aria-label="Previous chapter">‹</button><button class="demo-play" data-demo-play aria-label="Pause demo">Ⅱ</button><button data-demo-next aria-label="Next chapter">›</button><button data-demo-restart aria-label="Restart demo">↻</button></div><div class="demo-progress-area"><div class="demo-progress-label"><span data-demo-chapter>THE IDEA</span><span data-demo-step>01 / ${SCENES.length}</span></div><div class="demo-timeline"><i data-demo-progress></i></div></div><div class="demo-time"><span data-demo-time>0:00 / ${time(TOTAL_SECONDS)}</span><small>SPACE TO PAUSE · ESC TO EXIT</small></div></div>`;
    document.body.append(root);q('[data-demo-close]').onclick=stop;q('[data-demo-fullscreen]').onclick=fullscreen;q('[data-demo-play]').onclick=playPause;q('[data-demo-prev]').onclick=()=>seek(-1);q('[data-demo-next]').onclick=()=>seek(1);q('[data-demo-restart]').onclick=start;scene(clock.position());root.focus();document.addEventListener('keydown',key);document.addEventListener('visibilitychange',visibility);root.requestFullscreen?.().catch(()=>{});raf=requestAnimationFrame(frame);
  }
  return {start,stop,get active(){return Boolean(root);},get position(){return clock?.position()||null;}};
}
